values ('telc-b2', 'modell-08', 'FIRMENORGANIGRAMM', '54 Aufgaben · 125 Minuten',
        '[{"id": "block-lesen", "parts": ["lv1", "lv2", "lv3", "lv4"], "title": "Lesen", "minutes": 45, "hint": "Aufgaben 1–18", "maxPoints": 54, "availablePoints": 54, "missing": 0}, {"id": "block-lesen-schreiben", "parts": ["lvs1", "lvs2"], "title": "Lesen und Schreiben", "minutes": 20, "hint": "Aufgaben 19–20 und Beschwerde", "maxPoints": 13, "availablePoints": 13, "missing": 0}, {"id": "block-hoeren", "parts": ["hv1", "hv2", "hv3", "hv4"], "title": "Hören", "minutes": 20, "hint": "Aufgaben 22–40", "maxPoints": 57, "availablePoints": 57, "missing": 0}, {"id": "block-hoeren-schreiben", "parts": ["hvs"], "title": "Hören und Schreiben", "minutes": 5, "hint": "Aufgabe 41 und Telefonnotiz", "maxPoints": 9, "availablePoints": 9, "missing": 0}, {"id": "block-sb", "parts": ["sb1", "sb2", "fb"], "title": "Sprachbausteine und Schreiben", "minutes": 35, "hint": "Aufgaben 46–58", "maxPoints": 20, "availablePoints": 20, "missing": 0}]'::jsonb, 54, true, 8)
