insert into sections (test_id, section_id, "group", title, minutes, instruction, format, config, sort)
select t.id, v.section_id, v.grp, v.title, v.minutes, v.instruction, v.format, v.config, v.sort
from (values
    ('lv1', 'Lesen', 'Lesen, Teil 1', 10, 'Lesen Sie die Aufgaben 1–5 und die Informationen a–h. Welche Information passt zu welcher Situation?', 'matching', '{"bank": [{"key": "A", "text": "Internationale Fachkräfte gesucht: Im Ausland zu arbeiten, kann eine hervorragende Chance für Menschen in aller Welt sein. Erfahren Sie als Arbeitgeber, mit welchen Strategien Sie dringend benötigte Arbeitskräfte aus dem Ausland für sich gewinnen, um Ihr Unternehmen wettbewerbsfähiger zu machen."}, {"key": "B", "text": "Auf zu neuen Ufern! Im Job ist es nie zu spät, mit etwas Neuem zu beginnen, um sich weiterzuentwickeln. Manchmal fehlen nur ein bisschen Mut und Unterstützung. Oder man weiß erst gar nicht, welche Möglichkeiten es gibt. Eine gute Beratung ist darum wichtig. Wo Sie die bekommen, erfahren Sie hier."}, {"key": "C", "text": "Zufriedene Mitarbeiter: Viele Firmen überlegen, wie sie ihren Angestellten das Arbeitsleben abwechslungsreicher gestalten können. Manche schicken ihre Mitarbeitenden auf Dienstreisen ins Ausland, andere finanzieren ihnen Sprachkurse oder verteilen großzügig Prämien. Was noch möglich ist und wie sich das steuerlich auswirkt, erklärt der Steuerberater Michael Hahne."}, {"key": "D", "text": "Dschungel in der Arbeitswelt: Wie viel Urlaub steht einem zu? Wie viel sollte man in seinem Beruf verdienen? Wie viele Stunden arbeitet man üblicherweise? Bekommt man einen Zuschuss für Sprachkurse? Mit vielen gesetzlichen Dingen muss man sich auskennen, wenn man im Arbeitsleben steht. Die wichtigsten Informationen finden Sie hier zusammengefasst."}, {"key": "E", "text": "Chefsache: Ein erfolgreiches Unternehmen gibt es nur mit einem motivierten Team. Aber wie motiviert man seine Mitarbeiter? Hören Sie ihnen aufmerksam zu! Kontrollieren Sie nicht jeden Arbeitsschritt, sondern delegieren Sie! Nehmen Sie Mobbing ernst! Zahlen Sie faire Gehälter! Diese und noch viele andere Ratschläge lesen Sie hier."}, {"key": "F", "text": "Vielseitig qualifiziert! Von Arbeitnehmer*innen wird immer mehr verlangt. Nicht nur die aktuellen fachlichen Kenntnisse und die souveräne Arbeit mit dem PC sind eine Selbstverständlichkeit, sondern auch die sprachlichen Kompetenzen werden immer wichtiger. Hier findet jeder den richtigen Kurs für sich, von Englisch über Japanisch bis Suaheli."}, {"key": "G", "text": "Lassen Sie sich von Kolleg*innen den Arbeitsalltag nicht schwermachen: Sie erfahren von der Sitzung zuletzt? In der Kantine sitzen Sie allein? Es passiert immer häufiger in deutschen Unternehmen, dass manche Kollegen anderen das Leben aus unklaren Gründen schwermachen. Lesen Sie in diesem Ratgeber, wo Sie Hilfe bekommen können."}, {"key": "H", "text": "Den Horizont erweitern: Manche zieht die Liebe in ein anderes Land. Andere sehen dort interessantere berufliche Möglichkeiten. Manchmal ist das die reine Abenteuerlust. Auslandsaufenthalte können den Lebenslauf bereichern und ganz neue Karrierewege eröffnen."}], "bankTitle": "Informationen", "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 0),
    ('lv2', 'Lesen', 'Lesen, Teil 2', 15, 'Lesen Sie die Texte und die Aufgaben 6 bis 9. Entscheiden Sie, welche Lösung am besten passt.', 'mc', '{"passages": [{"paragraphs": [{"t": "Willkommensmappe für neue Mitarbeiterinnen und Mitarbeiter", "b": true}, {"t": "Firmenorganigramm", "b": true}, {"t": "Für Sie als neue Mitarbeiterin / neuer Mitarbeiter in unserem Traditionsunternehmen ist es wichtig zu wissen, wie das Unternehmen aufgebaut ist, d. h. welche Abteilungen es gibt, wer wofür verantwortlich ist und an wen Sie sich mit Ihren Fragen wenden können. Dafür wollen wir Ihnen im Folgenden Orientierung geben und hoffen, Ihnen den Einstieg in unser Unternehmen mit diesem Organigramm zu erleichtern.", "b": false}, {"t": "Das Dach unseres Unternehmens bildet die Geschäftsleitung. Hier laufen alle Fäden zusammen. Die nächste Ebene umfasst unsere Bereiche Produktion, Vertrieb und Personalwesen. In der Personalabteilung wenden Sie sich an Ihrem ersten Arbeitstag an Frau Müller. Von ihr erhalten Sie Ihren Mitarbeiterausweis, die für Sie notwendigen Schlüssel und die Arbeitskleidung. Für Urlaubsangelegenheiten steht Ihnen Herr Scholz zur Verfügung. Gehaltsfragen können Sie mit Herrn Kleinschmidt besprechen. Sollten Sie eine Dienstreise unternommen haben, rechnen Sie die entstandenen Kosten mit Herrn Friedrich ab.", "b": false}]}, {"paragraphs": [{"t": "Willkommensmappe für neue Mitarbeiterinnen und Mitarbeiter", "b": true}, {"t": "Arbeitsunfälle", "b": true}, {"t": "Arbeitsunfälle sind Unfälle, die Beschäftigte bei der Ausübung ihrer Arbeit oder einer Dienstreise erleiden. Es muss also ein ursächlicher Zusammenhang mit der beruflichen Tätigkeit bestehen.", "b": false}, {"t": "Nach einem Arbeitsunfall müssen Beschäftigte ihren Arbeitgeber umgehend über den Unfall in Kenntnis setzen und sich ggf. in Behandlung begeben. Außerdem ist, sobald es der Gesundheitszustand des Geschädigten zulässt, ein detaillierter Unfallbericht zu verfassen und der Personalabteilung vorzulegen.", "b": false}, {"t": "Im Falle einer Arbeitsunfähigkeit nach einem Arbeitsunfall erhalten Arbeitnehmende für sechs Wochen eine Lohnfortzahlung vom Arbeitgeber, danach übernimmt die Berufsgenossenschaft (BG), zahlt u. a. Verletztengeld in Höhe von 80 Prozent des Bruttogehalts und kommt ggf. auch für weitere Kosten auf.", "b": false}, {"t": "Zu Arbeitsunfällen zählen auch Wegeunfälle, also Unfälle, die sich auf dem direkten Weg zwischen dem Wohngebäude und der Arbeitsstätte ereignen. Dieser Weg beginnt vor der eigenen Haustür und endet, sobald die Arbeitnehmenden das Unternehmen erreicht haben. Dabei sind bestimmte notwendige Umwege mitversichert, wie etwa der Weg zur Kita, Umleitungen oder im Falle von Fahrgemeinschaften, unabhängig davon, mit welchen Verkehrsmitteln man sich fortbewegt. Der Versicherungsschutz umfasst ausschließlich Personenschäden; Sachschäden, wie z. B. Schäden am Fahrzeug, sind hierbei nicht mitversichert. Die BG übernimmt in diesem Fall z. B. die Behandlungskosten sowie ggf. Krankenpflege oder medizinische Rehabilitation.", "b": false}]}], "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 1),
    ('lv3', 'Lesen', 'Lesen, Teil 3', 10, 'Lesen Sie die Situationen 10–13 und die Beiträge a–f aus einem Online-Forum. Welcher Beitrag passt zu welcher Situation?', 'matching', '{"bank": [{"key": "A", "text": "Mario: Warte erst einmal ab, wie sich alles mit dem Kind entwickelt. Ich würde die Zeit nach der Geburt nicht mit Arbeit verplanen. Es ist nämlich eine große Umstellung. Wenn du dann später „Langeweile“ haben solltest, kannst du immer noch überlegen, arbeiten zu gehen."}, {"key": "B", "text": "Johann: Beides ist nicht ganz falsch – nach der Geburt des Kindes hat man bis zu drei Jahre Anspruch auf Freistellung von der Arbeit. 14 Monate erhält das Paar Elterngeld. Sowohl die bezahlte als auch die nicht bezahlte Zeit der Betreuung können die Eltern frei untereinander aufteilen."}, {"key": "C", "text": "Hanna: Elterngeld erhält man von der Elterngeldstelle. Die Höhe hängt davon ab, wie viel man vorher verdient hat. Vater und Mutter können die bezahlte Elternzeit von 14 Monaten untereinander aufteilen, wie es ihnen am besten passt. Allerdings ist die Frau die ersten acht Wochen im Mutterschutz."}, {"key": "D", "text": "Angela: Wenn du schon länger als sechs Monate bei einer Firma beschäftigt bist, kannst du beantragen, auch während der Elternzeit ein bisschen zu arbeiten. Du darfst dann allerdings nicht mehr als 30 Stunden pro Woche tätig sein. Der Betrieb kann den Antrag aber auch ablehnen."}, {"key": "E", "text": "Lars: Wenn eine Frau schwanger ist, kann sie, soweit es der Gesundheitszustand zulässt, bis sechs Wochen vor der Geburt arbeiten. Dann beginnt der Mutterschutz. Dieser gilt auch noch für acht Wochen nach der Geburt. Im Anschluss folgt die Elternzeit. Aber dafür gibt es wieder andere Regelungen."}, {"key": "F", "text": "Petra: Während der Schwangerschaft darf ein Arbeitgeber die Mitarbeiterin nicht nach 20 Uhr beschäftigen. Zwischen 20 und 22 Uhr kann man als Schwangere nur auf eigenen Wunsch arbeiten, der Arbeitgeber darf das nicht anordnen. Insgesamt darf eine Schwangere aber eine tägliche Arbeitszeit von 8,5 Stunden nicht überschreiten."}, {"key": "X", "text": "Keine Antwort passt"}], "bankTitle": "Forumsbeiträge", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 2),
    ('lv4', 'Lesen', 'Lesen, Teil 4', 10, 'Lesen Sie das Protokoll und die Aufgaben 14 bis 18. Entscheiden Sie, welche Lösung am besten passt.', 'mc', '{"passages": [{"paragraphs": [{"t": "Protokoll Sitzungsraum 112, Ort: Ludwigstr. 23, 79342 Herbolzen", "b": true}, {"t": "Anwesende: Jan Schneider (JS, Geschäftsleitung), Sabine Faust (SF, Leiterin Marketing), Paul Mayer (PM, Leiter Produktion), Tim Janzen (TJ, Leiter Vertrieb), Chiara Reich (CR, Leiterin IT), Simon Zitzmann (SZ, Leiter Personal), Mona Seil (MS, Leiterin Controlling)", "b": false}, {"t": "Sitzungsleitung: Jan Schneider", "b": false}, {"t": "Protokollant: Simon Zitzmann", "b": false}, {"t": "Tagesordnungspunkte:", "b": true}, {"t": "1. Begrüßung und Genehmigung der Tagesordnungspunkte", "b": false}, {"t": "2. Marketingmaßnahmen", "b": false}, {"t": "3. Berichte", "b": false}, {"t": "4. Erweiterte Überstundenregelung", "b": false}, {"t": "5. Einführung Jobticket", "b": false}, {"t": "6. Sonstiges", "b": false}, {"t": "TOP 1 Begrüßung und Genehmigung der Tagesordnungspunkte", "b": true}, {"t": "JS begrüßt die Abteilungsleitungen zur heutigen Sitzung, die daraufhin pünktlich eröffnet wird. Anschließend bittet er um die Genehmigung der Tagesordnungspunkte. Nach Handzeichen wird die Tagesordnung ohne Ergänzungen und Änderungen einstimmig genehmigt. Als nächster Besprechungstermin wird der 25.06. vor der großen Sommerpause einstimmig festgelegt.", "b": false}, {"t": "TOP 2 Marketingmaßnahmen", "b": true}, {"t": "Nach dem im letzten Quartal von MS und TJ festgestellten Absatzrückgang wurden bereits auf der letzten Sitzung neue Verkaufsstrategien beschlossen. Hierzu wurde von der Geschäftsleitung ein Budget von 350.000 Euro freigegeben. SF berichtet, dass schon im Vorfeld neue Zielgruppen beleuchtet wurden, insbesondere die Gruppe der Berufseinsteiger und Hochschulabsolventen, also die Altersgruppe 17 bis 25 Jahre. Im Vergleich dazu lag der Fokus bisher auf Verbrauchern im Alter von 30 bis 50 Jahren. Zunächst wurde eine Social-Media-Agentur beauftragt, um gezielt neue Endverbraucher anzusprechen. Hierzu liegen auch schon erste Ergebnisse vor, die zeigen, dass das Interesse und die Aufmerksamkeit um 38% gestiegen sind. Infolgedessen stieg der Umsatz um 18% im Vergleich zum Vorjahr. JS zeigt sich mit dieser ersten Entwicklung zufrieden und erwartet einen weiteren positiven Trend. Für das nächste Quartal ist geplant, positive Kundenreaktionen im Internet hochzuladen. SF betont, dass gerade in diesem Bereich die Zukunft liegt und regelmäßige Neuerungen erwartet werden können. Deshalb wird sie in den kommenden Sitzungen regelmäßig neue Konzepte präsentieren.", "b": false}, {"t": "TOP 3 Berichte", "b": true}, {"t": "SZ berichtet darüber, dass die Mitarbeitenden in der Produktion seit dem Einbau der neuen Maschinen gehäuft über eine enorme Lärmbelastung klagen würden. Hier bestehe dringender Handlungsbedarf, da im anderen Fall eine Überprüfung durch die Behörden erfolgen könnte. PM wird mit der Herstellerfirma dieser Anlagen Kontakt aufnehmen, um dieses Problem zu klären. Bis zur Lösung sollten Gehörschützer benutzt werden.", "b": false}, {"t": "TOP 4 Erweiterte Überstundenregelung", "b": true}, {"t": "JS teilt einen Vorschlag der Geschäftsleitung hinsichtlich einer erweiterten Überstundenregelung mit. Aufgrund einer sich ständig ändernden Auftragslage kommt es vor, dass den Mitarbeitenden immer mehr Überstunden zugemutet werden. Die bisherige Regelung, dass bis zehn Stunden Mehrarbeit im Monat bezahlt werden, bleibt bestehen. Die Stunden darüber hinaus werden weiterhin als Freizeitausgleich gewährt. Neu kommt hinzu, dass ab dem kommenden Jahr für jeweils 100 geleistete Überstunden jährlich ein Urlaubstag zusätzlich gegeben wird. SZ wird diese Maßnahme in der nächsten Betriebsratssitzung zur Prüfung und Genehmigung vorlegen.", "b": false}, {"t": "TOP 5 Einführung Jobticket", "b": true}, {"t": "Da in der Vergangenheit die Situation auf unseren Firmenparkplätzen sehr angespannt war, nahm die Firma Kontakt zum örtlichen öffentlichen Personennahverkehr auf, um die Einführung von Jobtickets für die Mitarbeitenden möglich zu machen. Viele Mitarbeitende hatten zuvor diesen Wunsch geäußert. SZ teilt mit, dass die Verhandlungen kurz vor dem Abschluss stehen. Wer Interesse an diesem günstigen Ticket hat, sollte sich per Mail oder persönlich in der Personalabteilung dafür anmelden. Die Abteilungsleiter übernehmen es, ihre Abteilungen zu informieren.", "b": false}, {"t": "TOP 6 Sonstiges", "b": true}, {"t": "Unser Unternehmen und das Fitnesscenter fit und fun, das sich in der unmittelbaren Nähe unserer Firma befindet, haben gemeinsam ein Angebot für unsere Mitarbeiter erarbeitet. Wenn man seine Betriebszugehörigkeit nachweist, kann man einen Vertrag zu besonders günstigen Konditionen abschließen. SZ schlägt vor, man könnte dort zu einem späteren Zeitpunkt sogar ein Sportfest für die Abteilungen durchführen. Diesen Vorschlag begrüßt JS.", "b": false}]}], "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 3),
    ('lvs1', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 1', 5, 'Lesen Sie die E-Mail und die Aufgaben 19 und 20. Entscheiden Sie, welche Lösung am besten passt.', 'mc', '{"passages": [{"paragraphs": [{"t": "Mangelhafte Lieferung", "b": true}, {"t": "Sehr geehrter Herr Mayer,", "b": false}, {"t": "leider müssen wir Ihnen mitteilen, dass Ihre Lieferung nicht zu unserer Zufriedenheit ausgefallen ist. Wir müssen zwei Punkte beanstanden: Erstens wurden die Verpackungen der Hosen (Größe M und L) beim Transport beschädigt, sodass der Inhalt verschmutzt ist. In diesem Zustand können wir die Waren auf keinen Fall in den regulären Verkauf geben, sondern sie nur mit einem Rabatt anbieten. Wir halten daher einen Preisnachlass von 60% für angemessen. Des Weiteren teilen wir Ihnen mit, dass von den T-Shirts mit Aufdruck statt der bezahlten 100 Stück nur die Hälfte geliefert wurde. Wegen der beginnenden Sommersaison bitten wir um schnellstmögliche Nachlieferung der fehlenden Stückzahl auf Ihre Kosten spätestens bis zum 10.05. Wir hoffen, dass sich derartige Vorkommnisse in Zukunft vermeiden lassen, und bitten um prompte Erledigung.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Matthias Schramm", "b": false}]}], "maxPoints": 6, "availablePoints": 6, "missing": 0, "pointsPerItem": 3}'::jsonb, 4),
    ('lvs2', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 2', 15, 'Antworten Sie auf die Beschwerde.', 'writing', '{"passages": [{"paragraphs": [{"t": "Arbeitsanweisung von Ihrem Teamleiter:", "b": true}, {"t": "Hallo, mich erreichte die untenstehende E-Mail von Herrn Schramm. Bitte kümmern Sie sich darum und antworten Sie dem Kunden höflich. Entschuldigen Sie sich für die verschmutzte Ware. Der geforderte Rabatt von 60% ist unverschämt. Bieten Sie ihm eine andere Lösung an. Die Nachlieferung der T-Shirts ist leider wegen unserer Personalsituation erst bis zum 12.05. möglich. Erklären Sie den Grund. Vielen Dank, Siegfried Mayer (Teamleiter).", "b": false}]}], "maxPoints": 7, "availablePoints": 7, "missing": 0, "pointsPerItem": 7}'::jsonb, 5),
    ('hv1', 'Hören', 'Hören, Teil 1', 6, 'Sie hören drei Gespräche. Zu jedem Gespräch gibt es zwei Aufgaben. Entscheiden Sie, ob die Aussage richtig oder falsch ist und welche Antwort am besten passt.', 'mc', '{"maxPoints": 18, "availablePoints": 18, "missing": 0, "pointsPerItem": 3, "audio": "telc-b2-m08-hv1.mp3", "audioPlays": 2}'::jsonb, 6),
    ('hv2', 'Hören', 'Hören, Teil 2', 5, 'Sie hören vier Personen über Fortbildungen sprechen. Welcher der Aussagen a–f passt zu welcher Person?', 'matching', '{"bank": [{"key": "A", "text": "Das Lernen hört im Arbeitsleben nie auf."}, {"key": "B", "text": "Die Firma sollte regelmäßig arbeitsplatzbezogene Schulungen organisieren."}, {"key": "C", "text": "Es ist sinnvoll, Fortbildungen an unterschiedlichen Tagen anzubieten."}, {"key": "D", "text": "Weiterbildungen sind nur mit hohem finanziellem Aufwand möglich."}, {"key": "E", "text": "Fortbildungen kosten vor allem wertvolle Arbeitszeit."}, {"key": "F", "text": "Nicht alle Schulungen müssen im Betrieb stattfinden."}], "bankTitle": "Aussagen", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3, "audio": "telc-b2-m08-hv2.mp3", "audioPlays": 2}'::jsonb, 7),
    ('hv3', 'Hören', 'Hören, Teil 3', 4, 'Sie hören eine Information für Mitarbeiterinnen und Mitarbeiter. Wählen Sie bei den Aufgaben 32 bis 35 die richtige Lösung.', 'mc', '{"maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3, "audio": "telc-b2-m08-hv3.mp3", "audioPlays": 2}'::jsonb, 8),
    ('hv4', 'Hören', 'Hören, Teil 4', 5, 'Sie hören fünf kurze Telefongespräche oder Ansagen. Zu jedem Text gibt es eine Aufgabe. Wählen Sie die richtige Lösung.', 'mc', '{"maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 9),
    ('hvs', 'Hören und Schreiben', 'Hören und Schreiben', 15, 'Hören Sie die Nachricht und füllen Sie die Telefonnotiz aus.', 'writing', '{"passages": [{"paragraphs": [{"t": "Telefonnotiz: Reklamation Weinlieferung", "b": true}, {"t": "Nachricht auf dem Anrufbeantworter von Herrn Guenther:", "b": false}, {"t": "„Guten Tag, hier ist Herr Guenther. Leider mussten wir feststellen, dass statt der 30 Kartons Rotwein nur 25 Kartons bei uns angekommen sind. Außerdem haben wir statt 15 Kartons Weißwein 30 Kartons bekommen. Aber vom Rotwein müssen Sie bitte schnell nachliefern. Darüber hinaus sind vom Saft zwei Flaschen kaputtgegangen. Bitte rufen Sie mich zurück. Mein Name ist Guenther, buchstabiert G-U-E-N-T-H-E-R. Meine Telefonnummer lautet 0135 821 76 49. Vielen Dank und auf Wiederhören.“", "b": false}]}], "maxPoints": 9, "availablePoints": 9, "missing": 0, "pointsPerItem": 9, "audio": "telc-b2-m08-hvs.mp3", "audioPlays": 2}'::jsonb, 10),
    ('sb1', 'Sprachbausteine', 'Sprachbausteine, Teil 1', 10, 'Lesen Sie den Text und schließen Sie die Lücken 46–51. Welches Wort aus der Liste a–j passt in welche Lücke?', 'matching', '{"bank": [{"key": "A", "text": "ABER"}, {"key": "B", "text": "AUF"}, {"key": "C", "text": "DA"}, {"key": "D", "text": "DEN"}, {"key": "E", "text": "DENNOCH"}, {"key": "F", "text": "DER"}, {"key": "G", "text": "DIESEM"}, {"key": "H", "text": "WENN"}, {"key": "I", "text": "WIE"}, {"key": "J", "text": "ZU"}], "bankTitle": "Wörterliste", "passages": [{"paragraphs": [{"t": "Kündigung", "b": true}, {"t": "Sehr geehrte Damen und Herren,", "b": false}, {"t": "mit (46) Schreiben kündige ich form- und fristgerecht meinen Arbeitsvertrag zum 31.12.20xx. Ich habe mir diese Entscheidung nicht leichtgemacht, (47) ich sehr gerne bei der MillerFood GmbH gearbeitet habe. (48) leider sehe ich hier im Unternehmen keine Möglichkeiten, mich weiterzuentwickeln, und habe mich deshalb dazu entschlossen, eine Stelle in einem größeren Unternehmen anzunehmen.", "b": false}, {"t": "Mir stehen noch vier Tage Resturlaub (49). Da in unserer Abteilung kurz vor dem Jahresende sehr viel zu tun ist, würde ich vorschlagen, dass Sie mir diese Tage auszahlen und ich noch bis zum Jahresende arbeite.", "b": false}, {"t": "Sollte das nicht möglich sein, ist mein letzter Arbeitstag der 23.12.20xx, da (50) 31.12.20xx auf einen Samstag fällt. Ich bitte um eine schriftliche Bestätigung über den Erhalt meiner Kündigung und den Bescheid, (51) wir mit den restlichen Urlaubstagen verfahren sollen.", "b": false}, {"t": "Ich bedanke mich für die Zusammenarbeit!", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Markus Stein", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 11),
    ('sb2', 'Sprachbausteine', 'Sprachbausteine, Teil 2', 10, 'Lesen Sie den Text und schließen Sie die Lücken 52–57. Welche Lösung passt am besten?', 'mc', '{"passages": [{"paragraphs": [{"t": "Beschwerde über Lieferverzögerung", "b": true}, {"t": "Sehr geehrte Damen und Herren,", "b": false}, {"t": "wir haben eine Bestellung aufgegeben und von Ihnen eine Bestätigung sowie einen Liefertermin erhalten. Sie hatten die Lieferung innerhalb von zwei Wochen zugesagt, jedoch ist die Ware (52) bei uns eingetroffen. Unser Kunde wartet bereits dringend auf diese Lieferung und wir möchten ihm keinesfalls (53).", "b": false}, {"t": "Bitte teilen Sie uns dringend mit, wann geliefert wird, (54) wir diese Auskunft an unseren Kunden weitergeben können.", "b": false}, {"t": "Außerdem müssen wir unserem Kunden wegen der Verzögerung einen Rabatt in Höhe von 2% einräumen. Dieser Betrag (55) Ihnen zur Last gelegt. Da der Kunde verständlicherweise verärgert ist, wird er bei Erhalt der Ware (56) Rechnungsbetrag nicht vollständig begleichen.", "b": false}, {"t": "Wir fordern Sie daher auf, uns (57) über den Lieferstatus zu informieren.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 12),
    ('fb', 'Sprachbausteine und Schreiben', 'Schreiben, Forumsbeitrag', 35, 'Wählen Sie eines der beiden Themen und schreiben Sie einen Forumsbeitrag von mindestens 100 Wörtern.', 'writing', '{"passages": [{"paragraphs": [{"t": "Thema A", "b": true}, {"t": "Homeoffice 2 Tage pro Woche mit privatem Laptop.", "b": false}, {"t": "Thema B", "b": true}, {"t": "Betriebsausflug am Samstag. Man darf aber einen Tag frei nehmen.", "b": false}]}], "maxPoints": 14, "availablePoints": 14, "missing": 0, "pointsPerItem": 14}'::jsonb, 13)
) as v(section_id, grp, title, minutes, instruction, format, config, sort)
join tests t on t.level_id = 'telc-b2' and t.slug = 'modell-08'
on conflict (test_id, section_id) do update set "group" = excluded."group", title = excluded.title, minutes = excluded.minutes, instruction = excluded.instruction, format = excluded.format, config = excluded.config, sort = excluded.sort;

insert into items (section_id, item_id, text, options, points, meta, sort)
select s.id, v.item_id, v.text, v.options, v.points, v.meta, v.sort
from (values
    ('lv1', '1', 'Barbara braucht beruflich Grundkenntnisse in Spanisch.', null::jsonb, 3, null::jsonb, 0),
    ('lv1', '2', 'Frank denkt, dass sein Gehalt nicht branchenüblich ist.', null::jsonb, 3, null::jsonb, 1),
    ('lv1', '3', 'Petra fühlt sich am Arbeitsplatz gemobbt.', null::jsonb, 3, null::jsonb, 2),
    ('lv1', '4', 'Sandra möchte im Ausland berufliche Erfahrungen sammeln.', null::jsonb, 3, null::jsonb, 3),
    ('lv1', '5', 'Felix möchte sich beruflich verändern.', null::jsonb, 3, null::jsonb, 4),
    ('lv2', '6', 'Den neuen Mitarbeitenden wird die Organisationsstruktur des Unternehmens vorgestellt.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('lv2', '7', 'In der Personalabteilung', '[{"key": "A", "text": "bekommen die Mitarbeitenden ihre Ausstattung."}, {"key": "B", "text": "bezahlt man die Arbeitskleidung."}, {"key": "C", "text": "bucht man Dienstreisen."}]'::jsonb, 3, null::jsonb, 1),
    ('lv2', '8', 'Im Falle eines Arbeitsunfalls muss man sofort einen Bericht beim Arbeitgeber einreichen.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 2),
    ('lv2', '9', 'Nach einem Arbeitsunfall', '[{"key": "A", "text": "bezahlt die Berufsgenossenschaft sofort Verletztengeld."}, {"key": "B", "text": "erhalten Arbeitnehmer sechs Wochen volles Gehalt."}, {"key": "C", "text": "trägt der Arbeitgeber die Kosten für die medizinische Versorgung."}]'::jsonb, 3, null::jsonb, 3),
    ('lv3', '10', 'Natalja: „Wir werden Eltern und wollen beide die bezahlte Elternzeit nehmen. Eine Freundin meinte, dass wir insgesamt ein Jahr zu Hause bleiben können. Ein anderer Bekannter sagte, man könne sein Kind bis zu drei Jahre zu Hause betreuen. Was stimmt?“', null::jsonb, 3, null::jsonb, 0),
    ('lv3', '11', 'Katrin: „Ich bin im vierten Monat schwanger. Mein Chef will, dass ich notfalls auch mal eine Spätschicht übernehme. Die geht bis 21:00 Uhr. Soviel ich weiß, ist das gar nicht erlaubt, oder? Außerdem bin ich abends immer sehr müde.“', null::jsonb, 3, null::jsonb, 1),
    ('lv3', '12', 'Giovanni: „Wir sind Auszubildende und bekommen bald ein Kind. Erst nach der Ausbildung wollen wir in Elternzeit gehen. Bis dahin könnte die Oma auf unser Kind aufpassen. Unser Betrieb wäre einverstanden. Weiß jemand, ob man die Elternzeit später beginnen darf?“', null::jsonb, 3, null::jsonb, 2),
    ('lv3', '13', 'Sandra: „Nach der Geburt bekomme ich Elterngeld. Finanziell mache ich mir keine Sorgen. Aber ich will beruflich den Anschluss nicht verlieren. Nur mit dem Kind zu Hause zu bleiben, ist nicht mein Ding. Kann man Elterngeld bekommen und gleichzeitig arbeiten?“', null::jsonb, 3, null::jsonb, 3),
    ('lv4', '14', 'Die Besprechung', '[{"key": "A", "text": "beginnt zur festgelegten Uhrzeit."}, {"key": "B", "text": "soll auf den 25.06. verlegt werden."}, {"key": "C", "text": "wird durch Änderungen ergänzt."}]'::jsonb, 3, null::jsonb, 0),
    ('lv4', '15', 'Die Umsatzsteigerung', '[{"key": "A", "text": "beträgt 350.000 Euro."}, {"key": "B", "text": "liegt bei 38 %."}, {"key": "C", "text": "wird sich fortsetzen."}]'::jsonb, 3, null::jsonb, 1),
    ('lv4', '16', 'Die Überstundenregelung', '[{"key": "A", "text": "bleibt genauso bestehen."}, {"key": "B", "text": "erhält eine Ergänzung."}, {"key": "C", "text": "gilt ab 100 Überstunden."}]'::jsonb, 3, null::jsonb, 2),
    ('lv4', '17', 'Das Jobticket', '[{"key": "A", "text": "ist eine preislich unattraktive Variante."}, {"key": "B", "text": "können die Mitarbeiter beim ÖPNV kaufen."}, {"key": "C", "text": "soll den Arbeitsweg stressfreier machen."}]'::jsonb, 3, null::jsonb, 3),
    ('lv4', '18', 'Sportliche Aktivitäten', '[{"key": "A", "text": "finden in dem Unternehmen statt."}, {"key": "B", "text": "sollen in den Abteilungen stattfinden."}, {"key": "C", "text": "werden von der Firma gefördert."}]'::jsonb, 3, null::jsonb, 4),
    ('lvs1', '19', 'Herr Schramm', '[{"key": "A", "text": "bemängelt Qualität und Menge der Lieferung."}, {"key": "B", "text": "fand die gesamte Lieferung beschädigt vor."}, {"key": "C", "text": "verlangt wegen der Lieferungsverzögerung einen Rabatt."}]'::jsonb, 3, null::jsonb, 0),
    ('lvs1', '20', 'Die Nachlieferung', '[{"key": "A", "text": "bezahlt der Kunde."}, {"key": "B", "text": "kommt im Sommer."}, {"key": "C", "text": "umfasst 50 T-Shirts."}]'::jsonb, 3, null::jsonb, 1),
    ('lvs2', 'B', 'Antworten Sie Herrn Schramm im Namen von Siegfried Mayer.', null::jsonb, 0, '{"points": ["Bedauern und Entschuldigung für die beschädigte Verpackung und verschmutzten Hosen", "Ablehnung des 60%-Rabatts und Angebot einer fairen Alternativlösung (z. B. Reinigungskostenübernahme)", "Zusage der Nachlieferung der fehlenden 50 T-Shirts bis zum 12.05.", "Begründung des Nachlieferungstermins mit der aktuellen personellen Engpasssituation"]}'::jsonb, 0),
    ('hv1', '22', 'Der Abteilungsleiter erklärt Jana wichtige Arbeitsschritte.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('hv1', '23', 'Jana', '[{"key": "A", "text": "arbeitet nicht immer an derselben Maschine."}, {"key": "B", "text": "bekommt jedes Jahr drei Schutzanzüge von der Firma."}, {"key": "C", "text": "braucht nicht überall in der Produktion eine Schutzausrüstung."}]'::jsonb, 3, null::jsonb, 1),
    ('hv1', '24', 'Im Café werden die heutigen Aufgaben verteilt.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 2),
    ('hv1', '25', 'Im Café', '[{"key": "A", "text": "erwartet man eine Lieferung am Nachmittag."}, {"key": "B", "text": "meldete sich heute eine Kollegin krank."}, {"key": "C", "text": "wird heute viel zu tun sein."}]'::jsonb, 3, null::jsonb, 3),
    ('hv1', '26', 'Frau Koch und der Lieferant sprechen einen Termin ab.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 4),
    ('hv1', '27', 'Die Möbelfirma', '[{"key": "A", "text": "arbeitet jeden Tag in der Woche."}, {"key": "B", "text": "benötigt zwei Tage für den Aufbau der Möbel."}, {"key": "C", "text": "hat die Bestellung am Mittwoch erhalten."}]'::jsonb, 3, null::jsonb, 5),
    ('hv2', '28', 'Sprecherin 1 meint, dass Schulungen nicht zwingend im eigenen Betrieb abgehalten werden müssen.', null::jsonb, 3, null::jsonb, 0),
    ('hv2', '29', 'Sprecherin 2 betont, dass lebenslanges Lernen und ständige Weiterbildung im Beruf unverzichtbar sind.', null::jsonb, 3, null::jsonb, 1),
    ('hv2', '30', 'Sprecher 3 plädiert dafür, dass das Unternehmen gezielte Schulungen für den Arbeitsalltag anbietet.', null::jsonb, 3, null::jsonb, 2),
    ('hv2', '31', 'Sprecher 4 findet flexible Termine und unterschiedliche Tage für Schulungsangebote wichtig.', null::jsonb, 3, null::jsonb, 3),
    ('hv3', '32', 'Ein Computer sollte', '[{"key": "A", "text": "nicht mehrmals ein- und ausgeschaltet werden."}, {"key": "B", "text": "nur selten ganz heruntergefahren werden."}, {"key": "C", "text": "von allein in den Ruhemodus schalten."}]'::jsonb, 3, null::jsonb, 0),
    ('hv3', '33', 'Frau Seibert empfiehlt,', '[{"key": "A", "text": "den Entwurfmodus zu verwenden."}, {"key": "B", "text": "immer Recyclingpapier zu benutzen."}, {"key": "C", "text": "Unterlagen für Kunden beidseitig zu bedrucken."}]'::jsonb, 3, null::jsonb, 1),
    ('hv3', '34', 'Frau Seibert findet es wichtig, dass', '[{"key": "A", "text": "die Firma den Müll sorgfältiger trennt."}, {"key": "B", "text": "mehr recycelt wird."}, {"key": "C", "text": "weniger Abfall produziert wird."}]'::jsonb, 3, null::jsonb, 2),
    ('hv3', '35', 'Geschäftsreisen', '[{"key": "A", "text": "lassen sich problemlos durch Videokonferenzen ersetzen."}, {"key": "B", "text": "mit der Bahn haben verschiedene Vorteile."}, {"key": "C", "text": "sind teurer, wenn sie umweltfreundlich sind."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '36', 'Andrea', '[{"key": "A", "text": "wird mit dem Vertreter frühstücken."}, {"key": "B", "text": "sagt den Termin ab."}, {"key": "C", "text": "möchte sich Montag wieder melden."}]'::jsonb, 3, null::jsonb, 0),
    ('hv4', '37', 'Frau Plassberg', '[{"key": "A", "text": "möchte eine Steuerprüfung auswerten."}, {"key": "B", "text": "möchte die neue Werbekampagne diskutieren."}, {"key": "C", "text": "möchte über die Dienstreise sprechen."}]'::jsonb, 3, null::jsonb, 1),
    ('hv4', '38', 'Daniela Schöller', '[{"key": "A", "text": "bittet um heutige Abholung der Ware."}, {"key": "B", "text": "braucht die Lieferung dringend."}, {"key": "C", "text": "hat den Eilzuschlag bezahlt."}]'::jsonb, 3, null::jsonb, 2),
    ('hv4', '39', 'Herr Lattermann', '[{"key": "A", "text": "bekommt eine Maschine aus Hamburg."}, {"key": "B", "text": "bestätigt den Empfang der Maschine."}, {"key": "C", "text": "liefert eine Maschine nach Dresden."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '40', 'Frau Bernhardt', '[{"key": "A", "text": "hat Änderungswünsche für die Homepage."}, {"key": "B", "text": "meldet sich bei ihrer Sekretärin."}, {"key": "C", "text": "möchte die Garantie verlängern."}]'::jsonb, 3, null::jsonb, 4),
    ('hvs', '41', 'Dokumentieren Sie die Kundenreklamation:', null::jsonb, 0, '{"points": ["Name des Anrufers (Herr Guenther, G-U-E-N-T-H-E-R)", "Telefonnummer (0135 821 76 49)", "Grund der Reklamation (Falschlieferung bei Rot- und Weißwein, Glasbruch)", "Details (25 statt 30 Kartons Rotwein geliefert, 30 statt 15 Kartons Weißwein geliefert, 2 Saftflaschen zerbrochen)", "Zu erledigen (Dringender Rückruf und sofortige Nachlieferung der 5 fehlenden Kartons Rotwein)"]}'::jsonb, 0),
